/* Recharts — carregado via CDN no HTML (script externo, assíncrono). */
/* Como o script pode ainda não ter terminado de carregar no momento  */
/* em que este código roda, usamos um hook que aguarda window.Recharts*/
/* aparecer e força a página a re-renderizar quando isso acontecer.   */
/* Assim os gráficos aparecem automaticamente, sem precisar recarregar*/
/* a página manualmente.                                              */
/* ------------------------------------------------------------------ */
function useRecharts() {
  const [rc, setRc] = useState(() => typeof window !== "undefined" ? window.Recharts : undefined);
  useEffect(() => {
    if (rc) return;
    let tentativas = 0;
    const id = setInterval(() => {
      tentativas++;
      if (window.Recharts) {
        setRc(window.Recharts);
        clearInterval(id);
      } else if (tentativas > 100) {
        // depois de ~20s desiste de tentar, mantém o fallback visual
        clearInterval(id);
      }
    }, 200);
    return () => clearInterval(id);
  }, [rc]);
  return rc;
}
