// Garante que uma chamada de armazenamento nunca trave a tela para sempre:
// se não responder dentro do tempo limite, rejeita com um erro tratável.
function withTimeout(promise, ms = 10000) {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      reject(new Error("Tempo de resposta esgotado."));
    }, ms);
    promise.then(value => {
      clearTimeout(timer);
      resolve(value);
    }, err => {
      clearTimeout(timer);
      reject(err);
    });
  });
}

