/* IMC – cálculo, classificação e faixas coloridas                   */
/* ---------------------------------------------------------------- */

function calcularIMC(peso, alturaCm) {
  const p = parseFloat(peso);
  const a = parseFloat(alturaCm);
  if (!p || !a) return null;
  const alturaM = a / 100;
  if (alturaM <= 0) return null;
  return p / (alturaM * alturaM);
}

// Faixas usadas tanto na classificação quanto no desenho da barra colorida.
// min/max em escala de exibição (a faixa final "Obesidade III" é aberta, mas
// na barra ela é representada até IMC_DISPLAY_MAX).
const IMC_DISPLAY_MIN = 14;
const IMC_DISPLAY_MAX = 42;
const FAIXAS_IMC = [{
  min: IMC_DISPLAY_MIN,
  max: 18.5,
  label: "Abaixo do peso",
  cor: "#3b82f6"
}, {
  min: 18.5,
  max: 25,
  label: "Peso normal",
  cor: "#22c55e"
}, {
  min: 25,
  max: 30,
  label: "Sobrepeso",
  cor: "#eab308"
}, {
  min: 30,
  max: 35,
  label: "Obesidade I",
  cor: "#f97316"
}, {
  min: 35,
  max: 40,
  label: "Obesidade II",
  cor: "#ef4444"
}, {
  min: 40,
  max: IMC_DISPLAY_MAX,
  label: "Obesidade III",
  cor: "#b91c1c"
}];
function classificarIMC(imc) {
  if (imc == null) return null;
  const faixa = FAIXAS_IMC.find(f => imc >= f.min && imc < f.max) || FAIXAS_IMC[FAIXAS_IMC.length - 1];
  return {
    valor: imc,
    label: faixa.label,
    cor: faixa.cor
  };
}

