/* ===== 08-pdf.jsx ===== */
const LOGO_BASE64_PDF = LOGO_DATA_URI;
async function gerarPDF(nomeAluno, secao, linhas, extra) {
  const agora = new Date();
  const dataStr = agora.toLocaleDateString("pt-BR") + " às " + agora.toLocaleTimeString("pt-BR", {
    hour: "2-digit",
    minute: "2-digit"
  });
  function renderLinhas(linhas) {
    return linhas.map(linha => {
      if (linha.tipo === "titulo") {
        return `<div class="titulo">${linha.texto}</div>`;
      } else if (linha.tipo === "subtitulo") {
        return `<div class="subtitulo">${linha.texto}</div>`;
      } else if (linha.tipo === "campo") {
        return `<div class="campo"><span class="label">${linha.label}:</span><span class="valor">${linha.valor || "—"}</span></div>`;
      } else if (linha.tipo === "texto") {
        return `<div class="texto">${linha.texto}</div>`;
      } else if (linha.tipo === "espaco") {
        return `<div style="height:${linha.h || 8}px"></div>`;
      }
      return "";
    }).join("");
  }
  const html = `<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="UTF-8">
<title>${nomeAluno} — ${secao}</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: Arial, Helvetica, sans-serif; font-size: 11pt; color: #1c1917; background: #fff; }
  .cabecalho { background: #1c1917; color: #fff; padding: 14px 20px 14px 20px; display: flex; align-items: center; justify-content: space-between; }
  .cabecalho-esq { display: flex; align-items: center; gap: 14px; }
  .logo { width: 40px; height: 60px; object-fit: contain; }
  .cabecalho-titulo { font-size: 15pt; font-weight: bold; }
  .cabecalho-sub { font-size: 9pt; color: #b4b4b4; margin-top: 2px; }
  .cabecalho-data { font-size: 8pt; color: #969696; text-align: right; }
  .aluno-header { padding: 16px 20px 8px 20px; border-bottom: 1px solid #ddd; }
  .aluno-nome { font-size: 14pt; font-weight: bold; }
  .aluno-secao { font-size: 10pt; color: #666; margin-top: 2px; }
  .conteudo { padding: 12px 20px 20px 20px; }
  .titulo { font-size: 11pt; font-weight: bold; color: #1c1917; margin: 14px 0 4px 0; padding-bottom: 3px; border-bottom: 1px solid #ccc; }
  .subtitulo { font-size: 10pt; font-weight: bold; font-style: italic; color: #064e3b; margin: 8px 0 4px 0; }
  .campo { display: flex; gap: 8px; margin: 4px 0; font-size: 10pt; }
  .label { font-weight: bold; color: #555; min-width: 150px; flex-shrink: 0; }
  .valor { color: #1e1e1e; }
  .texto { font-size: 10pt; color: #3c3c3c; margin: 4px 0; }
  .rodape { margin-top: 30px; padding-top: 8px; border-top: 1px solid #ddd; font-size: 8pt; color: #969696; display: flex; justify-content: space-between; }
  .barra-acoes { position: sticky; top: 0; z-index: 999; background: #f5f5f4; border-bottom: 1px solid #ddd; padding: 10px 20px; display: flex; justify-content: flex-end; gap: 10px; }
  .btn-baixar { display: inline-flex; align-items: center; gap: 6px; background: #064e3b; color: #fff; border: none; padding: 8px 16px; border-radius: 6px; font-size: 9pt; font-weight: bold; cursor: pointer; font-family: Arial, Helvetica, sans-serif; }
  .btn-baixar:hover { background: #053f30; }
  @media print {
    body { margin: 0; }
    @page { margin: 12mm 15mm; }
    .no-print { display: none !important; }
    .barra-acoes { display: none !important; }
  }
</style>
</head>
<body>
<div class="barra-acoes no-print">
  <button class="btn-baixar" onclick="window.print()">🖨️ Imprimir / Salvar PDF</button>
</div>
<div class="cabecalho">
  <div class="cabecalho-esq">
    <img class="logo" src="${LOGO_BASE64_PDF}" alt="Logo" onerror="this.style.display='none'" />
    <div>
      <div class="cabecalho-titulo">GINÁSIO COLISEU</div>
      <div class="cabecalho-sub">Sistema de Gestão de Alunos</div>
    </div>
  </div>
  <div class="cabecalho-data">${dataStr}</div>
</div>
<div class="aluno-header">
  <div class="aluno-nome">${nomeAluno}</div>
  <div class="aluno-secao">${secao}</div>
</div>
<div class="conteudo">
  ${renderLinhas(linhas)}
  <div class="rodape">
    <span>Ginásio Coliseu · Documento gerado automaticamente</span>
    <span>${dataStr}</span>
  </div>
</div>
<script>window.onload = function() { setTimeout(function(){ window.print(); }, 300); }<\/script>
</body>
</html>`;
  const blob = new Blob([html], {
    type: "text/html;charset=utf-8"
  });
  const url = URL.createObjectURL(blob);
  const janela = window.open(url, "_blank");
  if (!janela) {
    // fallback: download do HTML se popup bloqueado
    const a = document.createElement("a");
    a.href = url;
    a.download = `${nomeAluno.replace(/\s+/g, "_")}_${secao.replace(/\s+/g, "_")}.html`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  }
  setTimeout(() => URL.revokeObjectURL(url), 60000);
}
